import {addItem,countItem,removeItem} from './inventory.js';
import {maximum} from './player-stats.js';

export const RITUAL_OBJECTIVES={page_search:'Найдите недостающую страницу в доме ведьмы',page_return:'Верните страницу Джону',trial_ready:'Выпейте зелье внутренней тени',trial_fight:'Победите свою тёмную сторону',trial_return:'Вернитесь к Джону',ritual_done:''};
export function ritualQuest({p,slots,vitals,world,show,close,sync,sound,stats,reward}){
 let runes=[],unlocked=false,looted=false,buffs={hp:0,mana:0,strength:0,stew:0};
 function start(){p.stage='page_search';sound();sync();show('Джон','Кости собраны, но в записях ведьмы вырвана страница. Без неё круг не защитит тебя. Ведьма и Лич действовали сообща. Нам нужно остановить того, кто поднимает погибших. Найди страницу в её доме в глубинах Темнолесья. На двери тот же знак — теперь ты знаешь, как снять печать.')}
 function talk(){if(p.stage==='bones_done'){start();return true}if(p.stage==='page_return'&&countItem(slots,'ritual_page')){const copy=slots.map(i=>i?{...i}:null);removeItem(copy,'ritual_page');if(!addItem(copy,'ritual_elixir')){show('Джон','Освободи ячейку для зелья.');return true}slots.splice(0,slots.length,...copy);p.stage='trial_ready';sync();show('Джон','На странице описан защитный обряд для входа в проклятый склеп. Всякая злоба под его сводами разрастается в проклятие нежити. Прежде чем войти, победи собственную тень. Выпей это зелье там, куда захочешь вернуться. Если проиграешь, зелье позволит попробовать снова.');sound();return true}
  if(p.stage==='trial_return'){const id='ring_'+p.classId;if(!addItem(slots,id)){show('Джон','Освободи ячейку для кольца — ты заслужил его.');return true}p.stage='ritual_done';reward(p,'ritual-purified','quest',75);sync();sound();show('Джон','Зелье проверило, выдержишь ли ты проклятие склепа. Прими кольцо — оно поможет в бою. За дверью ждёт Лич, который поднимает наших мёртвых. Возьми мой оберег. Она связана с тобой и не займёт места в сумке: теперь дверь склепа пропустит тебя. Но будь осторожен — это лишь начало пути.');return true}
  if(Object.hasOwn(RITUAL_OBJECTIVES,p.stage)){show('Джон',p.stage==='page_search'?'Ищи страницу в сундуке ведьмы. Подсказка к замку должна быть рядом.':p.stage==='trial_ready'?'Выпей зелье из сумки, когда будешь готов. Твоя тень владеет тем же оружием и изученными приёмами.':p.stage==='ritual_done'?'Проход в склеп открыт. Под его сводами скрывается хозяин поднявшихся мертвецов.':'Заверши испытание и возвращайся.');return true}return false}
 function chest(){if(looted)return show('Сундук ведьмы','Сундук пуст.');if(unlocked)return claim();const order=['Луна','Кость','Пламя'];show('Замок трёх рун · шаг '+(runes.length+1)+' из 3','Нажмите три руны по порядку. Надпись: «Сначала Луна осветит могилу. Затем Кость вспомнит имя. И только Пламя отпустит душу».\nВыбрано: '+(runes.join(' → ')||'—')+(runes.length?'\nРуна принята. Выберите следующую.':''),[...order.filter(r=>!runes.includes(r)).map(r=>[r,()=>press(r)]),['Отойти',()=>{runes=[];close()}]])}
 function press(rune){const order=['Луна','Кость','Пламя'];if(rune!==order[runes.length]){runes=[];return show('Замок трёх рун','Руны погасли. Неверный порядок. Замок сброшен: Луна → Кость → Пламя.',[['Попробовать снова',chest],['Отойти',close]])}runes.push(rune);if(runes.length===3){unlocked=true;world.openChest();sound();claim()}else chest()}
 function claim(){const copy=slots.map(i=>i?{...i}:null);for(const [id,n] of [['health_potion',2],['mana_potion',1],['ritual_page',1]])if(!addItem(copy,id,n))return show('Открытый сундук','Внутри два зелья здоровья, зелье магии и недостающая страница. Освободите три ячейки в сумке и вернитесь.');slots.splice(0,slots.length,...copy);looted=true;p.stage='page_return';sync();show('Сундук ведьмы','Вы забрали два зелья здоровья, зелье магии и недостающую страницу. Вернитесь к Джону.')}
 function use(id){const resource=id==='health_potion'?'hp':id==='mana_potion'?'mana':id==='strength_potion'?'strength':null;if(resource){if(buffs[resource]>0){show('Зелье','Такое зелье уже действует.');return true}if(removeItem(slots,id)){buffs[resource]=resource==='strength'?90:10;sync();close()}return true}if(id!=='ritual_elixir')return false;if(p.stage!=='trial_ready')return true;if(world.beginTrial(stats())){p.stage='trial_fight';sync();close();sound()}return true}
 function tick(dt){buffs.stew=Math.max(0,(buffs.stew||0)-dt);for(const key of ['hp','mana','strength']){const step=Math.min(dt,buffs[key]);buffs[key]=Math.max(0,buffs[key]-dt);if(key!=='strength'&&vitals.hp>0)vitals[key]=Math.min(maximum(vitals,key),vitals[key]+5*step)}}
 function won(){if(p.stage!=='trial_fight')return;removeItem(slots,'ritual_elixir');p.stage='trial_return';sync();sound();show('Испытание завершено','Тёмная сторона повержена. Вы вернулись в своё тело. Расскажите Джону о победе.')}
 return {start,talk,chest,use,tick,won,get regenMultiplier(){return buffs.stew>0?1.5:1},get damageMultiplier(){return buffs.strength>0?1.4:1},get buffs(){return buffs},snapshot:()=>({runes:[...runes],unlocked,looted,buffs:{...buffs}}),restore(s){runes=s?.runes?[...s.runes]:[];unlocked=!!s?.unlocked;looted=!!s?.looted;buffs={hp:0,mana:0,strength:0,stew:0,...s?.buffs}},respawn(){if(p.stage==='trial_fight')p.stage='trial_ready';buffs={hp:0,mana:0,strength:0,stew:0}}};
}
